sksl:
uniform shader image;
uniform float2 size;
uniform float time;
uniform float mode;
uniform float offsetPx;
uniform float angle;
uniform float jitterAmt;
uniform float rate;
uniform float opacity;
float4 texT(float2 p) {
    return float4(image.eval(p));
}
half4 fin(float4 o, float4 r, float op) {
    return half4(mix(o, r, saturate(op)));
}
float hash21(float2 p) {
    return fract(sin(dot(p, float2(127.1, 311.7))) * 43758.5453);
}
half4 main(float2 coord) {
    float4 c = texT(coord);
    float2 off = float2(cos(radians(angle)), sin(radians(angle))) * offsetPx;
    if (mode > 1.5) {
        float t = floor(time * rate);
        off *= 1.0 + (hash21(float2(t, floor(coord.y / 8.0))) - 0.5) * 2.0 * jitterAmt * 3.0;
    }
    float4 cr = texT(coord + off);
    float4 cg = texT(coord);
    float4 cb = texT(coord - off);
    float4 r = float4(cr.r, cg.g, cb.b, max(max(cr.a, cg.a), cb.a));
    if (mode > 0.5 && mode < 1.5) r = float4(cr.r, cb.g, cb.b, max(cr.a, cb.a));
    return fin(c, r, opacity);
}
